//! CFF/OpenType outlines and TrueType Collections, through the public API.
//!
//! The `PxCff*` fonts are generated by `examples/cff_fonts.rs` (see
//! `tests/fonts/PROVENANCE`): an `.otf`, a bold `.otf`, a two-face `.ttc`, and the
//! regular face as WOFF 1.0 and WOFF 2.0. The same glyphs reached through every
//! container must agree, and every hostile mutation must return instead of panic.

use px_text::font::Font;
use px_text::sfnt::FontError;
use px_text::woff;
use px_text::{Outline, PathCmd};

const REGULAR: &[u8] = include_bytes!("../../../tests/fonts/PxCff-Regular.otf");
const BOLD: &[u8] = include_bytes!("../../../tests/fonts/PxCff-Bold.otf");
const TTC: &[u8] = include_bytes!("../../../tests/fonts/PxCff.ttc");
const WOFF1: &[u8] = include_bytes!("../../../tests/fonts/PxCff-Regular.woff");
const WOFF2: &[u8] = include_bytes!("../../../tests/fonts/PxCff-Regular.woff2");

fn all_outlines(f: &Font) -> Vec<Outline> {
    (0..f.num_glyphs())
        .map(|g| f.outline(g).expect("every glyph of the fixture draws"))
        .collect()
}

fn fingerprint(f: &Font) -> Vec<(u16, Outline)> {
    (0..f.num_glyphs())
        .map(|g| (f.advance(g).unwrap_or(0), f.outline(g).unwrap_or_default()))
        .collect()
}

#[test]
fn the_cff_fixture_loads_and_draws_every_glyph() {
    let f = woff::load_font(REGULAR).unwrap();
    assert!(f.is_cff());
    assert_eq!((f.units_per_em(), f.num_glyphs()), (1000, 64));
    assert_eq!((f.ascent(), f.descent()), (800, -200));
    let outlines = all_outlines(&f);
    // The space has no contours; everything else does, and every contour closes.
    for (g, o) in outlines.iter().enumerate() {
        assert_eq!(o.is_empty(), g == 1, "glyph {g}");
        let opens = o
            .commands
            .iter()
            .filter(|c| matches!(c, PathCmd::MoveTo(_)))
            .count();
        let closes = o
            .commands
            .iter()
            .filter(|c| matches!(c, PathCmd::Close))
            .count();
        assert_eq!(opens, closes, "glyph {g}");
    }
    // Curves came out as quadratics.
    assert!(
        outlines
            .iter()
            .any(|o| o.commands.iter().any(|c| matches!(c, PathCmd::QuadTo(..))))
    );
}

#[test]
fn cmap_advances_and_charstring_widths_agree() {
    for bytes in [REGULAR, BOLD] {
        let f = woff::load_font(bytes).unwrap();
        for c in ('A'..='Z').chain('a'..='z').chain('0'..='9').chain([' ']) {
            let g = f.glyph_index(c).unwrap();
            assert_eq!(
                f.charstring_width(g),
                f.advance(g).map(i32::from),
                "{c:?} (letters use defaultWidthX, digits and the space a width operand)"
            );
        }
        assert_eq!(f.glyph_index('\u{E000}'), None);
    }
    let r = woff::load_font(REGULAR).unwrap();
    let advance = |c: char| r.advance(r.glyph_index(c).unwrap());
    assert_eq!(
        (advance('A'), advance('a'), advance('7'), advance(' ')),
        (Some(600), Some(600), Some(650), Some(400))
    );
}

#[test]
fn shapes_have_the_designed_extents() {
    let f = woff::load_font(REGULAR).unwrap();
    let bounds = |c: char| f.outline(f.glyph_index(c).unwrap()).unwrap().bounds();
    // 'A': 65 % 7 = 2 -> 440 tall; a rounded rectangle from x 60 to 540.
    assert_eq!(bounds('A'), Some((60, 0, 540, 440)));
    // 'a': 97 % 7 = 6 -> 680 tall, with a dot centred at 300 reaching 830.
    let (x0, y0, x1, y1) = bounds('a').unwrap();
    assert_eq!((x0, y0, x1), (60, 0, 540));
    assert!((825..=840).contains(&y1), "{y1}");
    // Bold is wider and solid.
    let b = woff::load_font(BOLD).unwrap();
    let ba = b.outline(b.glyph_index('A').unwrap()).unwrap();
    assert_eq!(ba.bounds(), Some((40, 0, 640, 440)));
    let hollow = f.outline(f.glyph_index('A').unwrap()).unwrap();
    let moves = |o: &Outline| {
        o.commands
            .iter()
            .filter(|c| matches!(c, PathCmd::MoveTo(_)))
            .count()
    };
    assert_eq!((moves(&hollow), moves(&ba)), (2, 1));
}

#[test]
fn every_container_gives_the_same_font() {
    let want = fingerprint(&woff::load_font(REGULAR).unwrap());
    for (name, bytes) in [("woff", WOFF1), ("woff2", WOFF2), ("ttc", TTC)] {
        assert_eq!(
            fingerprint(&woff::load_font(bytes).unwrap()),
            want,
            "{name}"
        );
    }
    // The unwrapped form of each is a plain OTTO sfnt that parses on its own.
    for bytes in [WOFF1, WOFF2, TTC] {
        let sfnt = woff::to_sfnt(bytes).unwrap();
        assert_eq!(&sfnt[..4], b"OTTO");
        assert!(Font::from_bytes(sfnt).is_ok());
    }
}

#[test]
fn a_collection_face_is_chosen_by_index() {
    let regular = woff::load_font_face(TTC, 0).unwrap();
    let bold = woff::load_font_face(TTC, 1).unwrap();
    assert_eq!(
        fingerprint(&bold),
        fingerprint(&woff::load_font(BOLD).unwrap())
    );
    let a = |f: &Font| f.advance(f.glyph_index('A').unwrap());
    assert_eq!((a(&regular), a(&bold)), (Some(600), Some(700)));
    // Out of range, and a face index on something that is not a collection.
    assert!(woff::load_font_face(TTC, 2).is_err());
    assert!(woff::load_font_face(TTC, u32::MAX).is_err());
    assert!(woff::load_font_face(REGULAR, 1).is_err());
    assert!(woff::load_font_face(WOFF2, 1).is_err());
    // Font::from_bytes on the collection itself reads face 0.
    let direct = Font::from_bytes(TTC.to_vec()).unwrap();
    assert_eq!(fingerprint(&direct), fingerprint(&regular));
}

fn be32(v: &mut [u8], at: usize, x: u32) {
    v[at..at + 4].copy_from_slice(&x.to_be_bytes());
}

#[test]
fn collection_header_lies_are_refused() {
    // Declared face count: zero, huge, and past the offsets the file holds.
    for count in [0u32, 1000, u32::MAX, 3] {
        let mut f = TTC.to_vec();
        be32(&mut f, 8, count);
        let _ = woff::load_font_face(&f, 0);
        if count == 0 || count > 256 {
            assert!(woff::load_font_face(&f, 0).is_err(), "count {count}");
        }
    }
    // Face offsets: past the end, into the header, wrapping, and a nested ttcf.
    for off in [
        u32::MAX,
        0x7fff_ffff,
        TTC.len() as u32,
        TTC.len() as u32 - 3,
        0,
        4,
    ] {
        let mut f = TTC.to_vec();
        be32(&mut f, 12, off);
        assert!(woff::load_font_face(&f, 0).is_err(), "offset {off}");
    }
    // A face whose table record points outside the file.
    let mut f = TTC.to_vec();
    let face0 = u32::from_be_bytes(TTC[12..16].try_into().unwrap()) as usize;
    be32(&mut f, face0 + 12 + 8, u32::MAX);
    assert!(woff::load_font_face(&f, 0).is_err());
    // Too short to hold the header.
    for n in 0..16 {
        assert!(woff::load_font_face(&TTC[..n], 0).is_err());
    }
}

#[test]
fn cff2_and_a_missing_cff_table_are_named() {
    let at = REGULAR.windows(4).position(|w| w == b"CFF ").unwrap();
    let mut cff2 = REGULAR.to_vec();
    cff2[at..at + 4].copy_from_slice(b"CFF2");
    assert_eq!(
        woff::load_font(&cff2).unwrap_err(),
        FontError::Unsupported("CFF2 outlines")
    );
    let mut none = REGULAR.to_vec();
    none[at..at + 4].copy_from_slice(b"ZZZZ");
    assert_eq!(
        woff::load_font(&none).unwrap_err(),
        FontError::MissingTable("CFF ")
    );
}

#[test]
fn maxp_larger_than_the_charstrings_is_refused() {
    let dir = REGULAR
        .windows(4)
        .position(|w| w == b"maxp")
        .expect("maxp record");
    let off = u32::from_be_bytes(REGULAR[dir + 8..dir + 12].try_into().unwrap()) as usize;
    let mut f = REGULAR.to_vec();
    f[off + 4..off + 6].copy_from_slice(&65535u16.to_be_bytes());
    // hhea.numberOfHMetrics (64) is still <= numGlyphs; hmtx is fine; the
    // CharStrings INDEX is shorter than maxp says.
    assert_eq!(
        woff::load_font(&f).unwrap_err(),
        FontError::Malformed("CharStrings shorter than maxp")
    );
}

#[test]
fn every_truncation_of_every_container_returns() {
    for file in [REGULAR, WOFF1, WOFF2, TTC] {
        for n in 0..file.len() {
            let _ = woff::load_font(&file[..n]);
            let _ = woff::load_font_face(&file[..n], 1);
        }
    }
}

/// Every single-bit flip, and every glyph of whatever still parses drawn.
fn flip_everything(file: &[u8], stride: usize) {
    for i in (0..file.len() * 8).step_by(stride) {
        let mut m = file.to_vec();
        m[i / 8] ^= 1 << (i % 8);
        if let Ok(f) = woff::load_font(&m) {
            for g in 0..f.num_glyphs().min(24) {
                let _ = f.outline(g);
            }
        }
        let _ = woff::load_font_face(&m, 1);
    }
}

#[test]
fn every_bit_flip_returns_instead_of_panicking() {
    flip_everything(REGULAR, 2);
    flip_everything(TTC, 7);
    flip_everything(WOFF2, 13);
}

#[test]
fn byte_stomping_inside_the_cff_table_never_panics() {
    let at = REGULAR
        .windows(4)
        .position(|w| w == b"CFF ")
        .expect("CFF record");
    let off = u32::from_be_bytes(REGULAR[at + 8..at + 12].try_into().unwrap()) as usize;
    let len = u32::from_be_bytes(REGULAR[at + 12..at + 16].try_into().unwrap()) as usize;
    for i in off..off + len {
        for v in [0u8, 1, 0x80, 0xff, 0x1d, 0x1c, 0x0b, 0x0a, 0x13] {
            let mut m = REGULAR.to_vec();
            m[i] = v;
            if let Ok(f) = Font::from_bytes(m) {
                for g in 0..f.num_glyphs() {
                    let _ = f.outline(g);
                }
            }
        }
    }
}

#[test]
fn pseudo_random_garbage_behind_cff_signatures_never_panics() {
    let mut x: u32 = 0x9e37_79b9;
    let mut next = move || {
        x = x.wrapping_mul(1_664_525).wrapping_add(1_013_904_223);
        (x >> 24) as u8
    };
    for sig in [&b"OTTO"[..], b"ttcf", &[0, 1, 0, 0]] {
        for _ in 0..300 {
            let mut buf = sig.to_vec();
            buf.extend((0..300).map(|_| next()));
            let _ = woff::load_font(&buf);
            let _ = woff::load_font_face(&buf, 1);
        }
    }
    // The CFF table itself replaced by noise inside a valid sfnt.
    let at = REGULAR.windows(4).position(|w| w == b"CFF ").unwrap();
    let off = u32::from_be_bytes(REGULAR[at + 8..at + 12].try_into().unwrap()) as usize;
    let len = u32::from_be_bytes(REGULAR[at + 12..at + 16].try_into().unwrap()) as usize;
    for _ in 0..300 {
        let mut m = REGULAR.to_vec();
        for b in m.iter_mut().skip(off).take(len) {
            *b = next();
        }
        if let Ok(f) = Font::from_bytes(m) {
            for g in 0..f.num_glyphs() {
                let _ = f.outline(g);
            }
        }
    }
}

#[test]
fn outlines_are_deterministic() {
    let a = fingerprint(&woff::load_font(REGULAR).unwrap());
    let b = fingerprint(&woff::load_font(REGULAR).unwrap());
    assert_eq!(a, b);
}
